import { CreateMLCEngine, type MLCEngine } from "@mlc-ai/web-llm";
import type { LocalRuntime } from "@hybrid-ai/core";

/** LocalRuntime backed by WebLLM (WebGPU path). */
export class WebLLMAdapter implements LocalRuntime {
  private engine: MLCEngine | null = null;

  async load(modelId: string, onProgress?: (pct: number, text: string) => void): Promise<void> {
    this.engine = await CreateMLCEngine(modelId, {
      initProgressCallback: (p) => onProgress?.(p.progress, p.text),
    });
  }

  async generate(prompt: string): Promise<string> {
    if (!this.engine) throw new Error("WebLLMAdapter: load() must be called before generate()");

    const reply = await this.engine.chat.completions.create({
      messages: [{ role: "user", content: prompt }],
    });

    return reply.choices[0]?.message?.content ?? "";
  }
}